import {val,eq} from './b36-model.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(action,label,index,pressed=false)=>`<button type="button" data-x="r37-${action}"${index===undefined?'':` data-index="${esc(index)}"`} aria-pressed="${!!pressed}">${esc(label)}</button>`;
const field=(key,label,value)=>`<label class="r37-field"><span>${esc(label)}</span><input data-xfield="${esc(key)}" value="${esc(value)}" autocomplete="off" maxlength="160"></label>`;
const select=(key,label,value,items)=>`<label class="r37-field"><span>${esc(label)}</span><select data-xfield="${esc(key)}"><option value="">选择</option>${items.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const caption=s=>`<div class="r37-caption">${esc(s)}</div>`;
function inverseGraph(t,b){if(!t.graph||b.records.filter(r=>r.correct).length<2)return '';const k=val(t.base[0])*val(t.base[1]),maxX=Math.ceil(Math.max(...[t.base,...t.targets].map(p=>val(p[0])))*1.2/5)*5,maxY=Math.ceil(Math.max(...[t.base,...t.targets].map(p=>val(p[1])))*1.2/5)*5,minX=k/maxY,X=x=>42+x/maxX*260,Y=y=>220-y/maxY*180;const line=Array.from({length:101},(_,i)=>{const x=minX+(maxX-minX)*i/100;return `${i?'L':'M'}${X(x).toFixed(2)},${Y(k/x).toFixed(2)}`;}).join(' '),ticks=Array.from({length:6},(_,i)=>{const x=maxX*i/5,y=maxY*i/5;return `<line x1="${X(x)}" y1="40" x2="${X(x)}" y2="220" stroke="#e5ede6"/><line x1="42" y1="${Y(y)}" x2="302" y2="${Y(y)}" stroke="#e5ede6"/><text x="${X(x)}" y="236" text-anchor="middle">${x}</text><text x="34" y="${Y(y)+4}" text-anchor="end">${y}</text>`;}).join('');return `<svg class="r37-graph" viewBox="0 0 330 260" role="img" aria-label="人数与时间的反向变化图">${ticks}<path d="M42 30V220H305" fill="none" stroke="#718c7a" stroke-width="2"/><path d="${line}" fill="none" stroke="#8d7eae" stroke-width="3"/>${[t.base,...b.records.filter(r=>r.correct).map(r=>r.pair)].map(p=>`<circle cx="${X(val(p[0]))}" cy="${Y(val(p[1]))}" r="5" fill="#c1816b"/><text x="${X(val(p[0]))+7}" y="${Y(val(p[1]))-6}">(${esc(p[0])},${esc(p[1])})</text>`).join('')}<text x="275" y="253">${esc(t.labels[0])}</text><text x="8" y="22">${esc(t.labels[1])}</text></svg><p class="r37-note">曲线由系统按乘积不变绘出；人数和时间都不能是0。</p>`;}
function pair(t,m){const b=m.board,sets=[t.base,...(b.preview?[b.preview]:[])],maxAll=Math.max(1,...sets.flat().map(val)),maxima=t.commonUnit===false?[0,1].map(i=>Math.max(1,...sets.map(p=>val(p[i])))):[maxAll,maxAll],bar=(v,color,i)=>`<div class="r37-bar-track"><span style="width:${Math.max(0,val(v)/maxima[i]*100)}%;background:${color}"></span></div><b>${esc(v)}</b>`,last=b.records.at(-1),fresh=last&&b.preview&&eq(last.pair[0],b.preview[0])&&eq(last.pair[1],b.preview[1])&&eq(m.value,b.preview[0])&&eq(m.second,b.preview[1])&&m.choice===last.guess,feedback=!last?'':!fresh?'这一组还没比较，先判断并留下。':!last.correct?'再看两边各怎样变化。':t.relation==='inverse'?(last.relation==='same'?'两个量相乘，积仍然相同。':'两个量相乘，积已经改变。'):(last.relation==='same'?'两种量同时乘了同一个数。':'两种量乘的倍数不同。');return `${caption(t.caption||(t.commonUnit===false?'每种量按自己的单位，对比前后':'把两种量放在同一把尺上'))}${sets.map((p,i)=>`<section class="r37-pair-set"><strong>${i?'这次摆出的':'原来的'}</strong><div>${esc(t.labels?.[0]||'第一种')}${bar(p[0],'#cd9980',0)}</div><div>${esc(t.labels?.[1]||'第二种')}${bar(p[1],'#80a89c',1)}</div></section>`).join('')}${t.commonUnit===false?'<p class="r37-note">两种量使用不同刻度，条长只比较同一种量前后的变化。</p>':''}${last?`<p class="r37-note">已留下 ${b.records.length} 次比较。${feedback}</p>`:''}${inverseGraph(t,b)}`;}
function share(t,m){const b=m.board,colors=['#cc9881','#7fa79b','#b49ac6'];return `${caption('每一块一样大，自己把它们分出去')}<p>整个：${esc(t.total)} ${esc(t.unit||'个')}</p><div class="r37-owners">${t.parts.map((_,i)=>btn('person',t.labels?.[i]||String.fromCharCode(65+i),i,b.owner===i)).join('')}</div><div class="r37-slots">${b.slots.map((v,i)=>`<button type="button" data-x="r37-slot" data-index="${i}" style="--piece:${v<0?'#edf1ea':colors[v]}" aria-label="第 ${i+1} 份，${v<0?'未分配':esc(t.labels?.[v]||String.fromCharCode(65+v))}">${v<0?'＋':esc(t.labels?.[v]||String.fromCharCode(65+v))}</button>`).join('')}</div><p class="r37-note">先选要分给谁，再点一份；再点已分给同一人的份可以拿回。</p>`;}
function shape(t,m){const b=m.board,f=val(b.factor),w=val(t.base[0]),h=val(t.base[1]),largest=Math.max(...t.factors.map(val)),k=Math.min(55,260/(w*largest),200/(h*largest)),y=215,x1=75,x2=380,rect=(x,width,height,fill)=>`<rect x="${x}" y="${y-height*k}" width="${width*k}" height="${height*k}" fill="${fill}" stroke="#587e6d" stroke-width="2"/>`;let grid='';if(t.tiles&&Number.isSafeInteger(f)&&f>0&&f<=5){for(let i=1;i<f;i++)grid+=`<path d="M${x2+i*w*k} ${y-h*f*k}v${h*f*k} M${x2} ${y-i*h*k}h${w*f*k}" stroke="#7f9682" fill="none"/>`;}
 const last=b.records.at(-1),fresh=last&&eq(last.factor,b.factor)&&eq(last.width,m.value)&&eq(last.height,m.second);return `${caption('两幅图用同样大小的单位') }<svg class="r37-shape" viewBox="0 0 720 260" role="img" aria-label="原长方形与按所选倍数改变的长方形">${rect(x1,w,h,'#dcebdd')}${rect(x2,w*f,h*f,'#d4e3ef')}${grid}<text x="${x1}" y="239">原来：${esc(t.base[0])} × ${esc(t.base[1])}</text><text x="${x2}" y="239">这次：${esc(b.factor)} 倍</text></svg>${t.tiles&&Number.isSafeInteger(f)&&f>0?'<p class="r37-note">右图每一小块和左图一样大。</p>':''}${last&&!fresh?'<p>倍数或记录改了，再对照一次。</p>':last?`<p>${last.correct?'对应边与记录一致。':'再比较两条对应边。'}</p>`:''}`;}
function steps(t,m){const b=m.board;return `${caption(t.caption||'把同一件事拆成几步')}${t.scene?`<p class="r37-scene">${esc(t.scene)}</p>`:''}<div class="r37-path">${t.steps.map((s,i)=>{const done=b.records.filter(r=>r.index===i&&r.correct).at(-1);return `<div class="${i===b.index?'current':''}"><span>${esc(s.title)}</span><b>${done?esc(done.answer):'？'}</b></div>`;}).join('')}</div>`;}
export function visual(t,m){return `<div class="r37-world">${t.type==='x-r37-pair'?pair(t,m):t.type==='x-r37-share'?share(t,m):t.type==='x-r37-shape'?shape(t,m):steps(t,m)}</div>`;}
export function controls(t,m){let s='<div class="r37-controls">';const b=m.board;
 if(t.type==='x-r37-pair'){s+=field('value',t.labels?.[0]||'第一种数量',m.value)+field('second',t.labels?.[1]||'第二种数量',m.second)+btn('place','把这两个量摆出来');if(b.preview)s+=select('choice',t.relation==='inverse'?'乘积还一样吗？':t.commonUnit===false?'两种量的对应关系还一样吗？':'两种量的配比还一样吗？',m.choice,[['same','保持一样'],['different','已经改变']])+btn('save','留下这次比较');}
 if(t.type==='x-r37-shape')s+=`<div class="r37-factors">${t.factors.map(f=>btn('factor',f+' 倍',f,eq(b.factor,f))).join('')}</div>`+field('value','这次长是多少',m.value)+field('second','这次宽是多少',m.second)+btn('save','留下并对照');
 if(t.type==='x-r37-steps'&&b.index<t.steps.length){const st=t.steps[b.index];s+=st.kind==='choice'?select('choice',st.label,m.choice,st.options):field('value',st.label,m.value);s+=btn('step','把这一步放上图');}
 let ready=true;const last=b.records?.at(-1);if(t.type==='x-r37-pair')ready=t.targets.every(p=>b.records.some(r=>r.correct&&eq(r.pair[0],p[0])&&eq(r.pair[1],p[1])))&&!!last?.correct&&!!b.preview&&eq(last.pair[0],b.preview[0])&&eq(last.pair[1],b.preview[1])&&eq(m.value,b.preview[0])&&eq(m.second,b.preview[1])&&m.choice===last.guess;if(t.type==='x-r37-share')ready=b.slots.every(n=>n>=0);if(t.type==='x-r37-shape')ready=t.required.every(f=>b.records.some(r=>r.correct&&eq(r.factor,f)))&&!!last?.correct&&eq(last.factor,b.factor)&&eq(last.width,m.value)&&eq(last.height,m.second);
 if(!ready&&(t.questions||[]).length)s+='<p class="r37-note">先把图中的这一步做完，接着再记录发现。</p>';
 if(ready)for(const[i,q]of(t.questions||[]).entries())s+=q.options?select('answers.'+i,q.label,m.answers[i],q.options):field('answers.'+i,q.label,m.answers[i]);
 if(m.issue)s+=`<p class="r37-issue" role="status">${esc(m.issue)}</p>`;
 return s+`<details><summary>留下自己的想法（可选）</summary>${field('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断。</small></details></div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
